package crap_test

import (
	"errors"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/Hedronite/go-tops/internal/crap"
	"github.com/Hedronite/go-tops/internal/gobuild"
)

func keysOf(rep crap.Report) []string {
	var keys []string
	for _, f := range rep.Measured {
		keys = append(keys, f.Key)
	}
	slices.Sort(keys)
	return keys
}

// Scope (§6.2): every production function; _test.go files, generated files and
// testdata are out. So are vendor, dot and underscore directories and nested
// modules, which are not the module's own packages.
func TestScope(t *testing.T) {
	gen := "// Code generated by a tool. DO NOT EDIT.\n\npackage m\n\nfunc FromHeader() {}\n"
	dir := fixtureModule(t, map[string]string{
		"m.go":              "package m\n\nfunc Prod() { println() }\n",
		"m_test.go":         "package m\n\nimport \"testing\"\n\nfunc TestProd(t *testing.T) {}\n\nfunc helper() {}\n",
		"gen.go":            gen,
		"z.gen.go":          "package m\n\nfunc FromName() {}\n",
		"testdata/t.go":     "package td\n\nfunc InTestdata() {}\n",
		"vendor/v/v.go":     "package v\n\nfunc InVendor() {}\n",
		".hidden/h.go":      "package h\n\nfunc InDot() {}\n",
		"_skip/u.go":        "package u\n\nfunc InUnderscore() {}\n",
		"sub/go.mod":        "module example.com/other\n\ngo 1.26\n",
		"sub/s.go":          "package sub\n\nfunc InNestedModule() {}\n",
		"inner/deeper/d.go": "package deeper\n\nfunc Deep() {}\n",
	})
	prof := profile(t, dir, block("m.go", 3, 14, 3, 25, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	want := []string{module + ".Prod", module + "/inner/deeper.Deep"}
	if got := keysOf(rep); !slices.Equal(got, want) {
		t.Errorf("scored %v, want %v", got, want)
	}
	// Out of scope is out of the existence set too, not merely unscored.
	if got := rep.Keys(); !slices.Equal(got, want) {
		t.Errorf("existence set %v, want %v", got, want)
	}
}

// A profile with no block of any production file fails the layer (§3.4 rule 5):
// it is empty of them, or every block is in an excluded file.
func TestProfileWithNoProductionBlockFails(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"m.go":      "package m\n\nfunc Prod() {}\n",
		"m_test.go": "package m\n\nfunc helper() {}\n",
	})
	onlyTests := profile(t, dir, block("m_test.go", 3, 1, 3, 20, 1, 1))
	if _, err := crap.Score(dir, onlyTests, crap.Options{Build: linux}); !errors.Is(err, crap.ErrNoBlocks) {
		t.Errorf("a profile of a test file only: err = %v, want ErrNoBlocks", err)
	}
	other := "mode: atomic\nexample.org/elsewhere/x.go:1.1,2.2 1 1\n"
	write(t, filepath.Join(dir, "other.out"), other)
	if _, err := crap.Score(dir, filepath.Join(dir, "other.out"), crap.Options{Build: linux}); !errors.Is(err, crap.ErrNoBlocks) {
		t.Errorf("a profile of another module: err = %v, want ErrNoBlocks", err)
	}
}

func TestProfileErrors(t *testing.T) {
	dir := fixtureModule(t, map[string]string{"m.go": "package m\n\nfunc Prod() {}\n"})
	if _, err := crap.Score(dir, filepath.Join(dir, "absent.out"), crap.Options{Build: linux}); err == nil {
		t.Error("a missing profile scored")
	}
	write(t, filepath.Join(dir, "empty.out"), "  \n")
	if _, err := crap.Score(dir, filepath.Join(dir, "empty.out"), crap.Options{Build: linux}); err == nil {
		t.Error("an empty profile scored")
	}
	write(t, filepath.Join(dir, "bad.out"), "mode: atomic\nnot a block\n")
	if _, err := crap.Score(dir, filepath.Join(dir, "bad.out"), crap.Options{Build: linux}); err == nil {
		t.Error("a malformed profile scored")
	}
}

// Identity (§6.7): import path, receiver and name; where that key repeats in a
// package, the file name; where it still repeats in a file, its position.
func TestIdentity(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"a.go":   "package m\n\nfunc init() { println(1) }\n\nfunc init() { println(2) }\n\nfunc Helper() {}\n",
		"b.go":   "package m\n\nfunc init() { println(3) }\n\ntype T struct{}\n\nfunc (T) Run() {}\n\nfunc (*T) Stop() {}\n",
		"p/p.go": "package p\n\nfunc Helper() {}\n",
		"p/x.go": "package p\n\nfunc init() {}\n",
		"p/y.go": "package p\n\nfunc init() {}\n",
	})
	prof := profile(t, dir, block("a.go", 3, 14, 3, 25, 1, 1))
	got := keysOf(scoreOf(t, dir, prof, true))
	want := []string{
		module + ".Helper",
		module + ".T.Run",
		module + ".T.Stop",
		module + ".init@a.go#1",
		module + ".init@a.go#2",
		module + ".init@b.go",
		module + "/p.Helper",
		module + "/p.init@x.go",
		module + "/p.init@y.go",
	}
	if !slices.Equal(got, want) {
		t.Errorf("keys\n got  %v\n want %v", got, want)
	}
}

// Build-tagged twins count whatever their tags (§6.7): two files that declare
// one function get file-name keys on a run that compiles only one of them, and
// the twin the run does not compile is not scored cov 0 (ruling C2).
func TestTwinsAreNotMeasuredNotZero(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"x_linux.go":   "package m\n\nfunc Foo() int { return 1 }\n",
		"x_windows.go": "package m\n\nfunc Foo() int { return 2 }\n",
	})
	prof := profile(t, dir, block("x_linux.go", 3, 17, 3, 27, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	if len(rep.Measured) != 1 || rep.Measured[0].Key != module+".Foo@x_linux.go" || rep.Measured[0].Cov != 1 {
		t.Fatalf("measured %+v, want Foo@x_linux.go at cov 1", rep.Measured)
	}
	if len(rep.NotMeasured) != 1 || rep.NotMeasured[0].Key != module+".Foo@x_windows.go" || rep.NotMeasured[0].File != "x_windows.go" {
		t.Fatalf("not measured %+v, want Foo@x_windows.go", rep.NotMeasured)
	}
}

// Ruling C2b: a function the run's build does not compile is still counted. Its
// file is loaded for a GOOS and GOARCH that compile it, so the guard discount
// applies; a file no platform compiles (a tag) is counted without the discount,
// which errs high.
func TestNotMeasuredFunctionsAreCounted(t *testing.T) {
	guard := "package m\n\nfunc mk%s() error { return nil }\n\nfunc %s() error {\n\terr := mk%s()\n\tif err != nil {\n\t\treturn err\n\t}\n\treturn nil\n}\n"
	big := "package m\n\nfunc Big(a bool) int {\n" + strings.Repeat("\tif a {\n\t\treturn 1\n\t}\n", 11) + "\treturn 0\n}\n"
	dir := fixtureModule(t, map[string]string{
		"main.go":        "package m\n\nfunc Run() { println() }\n",
		"w_windows.go":   strings.NewReplacer("%s", "W").Replace(guard),
		"tagged.go":      "//go:build integration\n\n" + strings.NewReplacer("%s", "T").Replace(guard),
		"big_windows.go": big,
	})
	prof := profile(t, dir, block("main.go", 3, 14, 3, 25, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	got := map[string]crap.NotMeasured{}
	for _, f := range rep.NotMeasured {
		got[f.Name] = f
	}
	if w := got["W"]; w.Comp != 1 || !w.Typed {
		t.Errorf("W (windows file): %+v, want comp 1 typed: the guard is discounted", w)
	}
	if tg := got["T"]; tg.Comp != 2 || tg.Typed {
		t.Errorf("T (tagged file): %+v, want comp 2 untyped: no platform compiles it", tg)
	}
	if b := got["Big"]; b.Comp != 12 || !b.Typed {
		t.Errorf("Big: %+v, want comp 12", b)
	}
	if len(rep.Measured) != 1 || rep.Measured[0].Name != "Run" {
		t.Errorf("measured %+v, want Run only", rep.Measured)
	}
	_, over := rep.Over(10)
	if len(over) != 1 || over[0].Name != "Big" {
		t.Errorf("over the cap 10 and not measured: %+v, want Big", over)
	}
	if _, at := rep.Over(12); len(at) != 0 {
		t.Errorf("comp 12 is at a cap of 12, not over it: %+v", at)
	}

	// With the discount off nothing is typed, and the figures are the plain count.
	off := scoreOf(t, dir, prof, false)
	for _, f := range off.NotMeasured {
		if f.Typed || (f.Name == "W" && f.Comp != 2) {
			t.Errorf("discount off: %+v, want untyped and W at comp 2", f)
		}
	}
}

// Over compares unrounded: a measured function at 8.000064 is over a cap of 8.
func TestOverIsUnrounded(t *testing.T) {
	rep := crap.Report{Measured: []crap.Function{
		{Name: "a", CRAP: 8.000064}, {Name: "b", CRAP: 8}, {Name: "c", CRAP: 7.9},
	}}
	over, _ := rep.Over(8)
	if len(over) != 1 || over[0].Name != "a" {
		t.Errorf("over = %+v, want only a", over)
	}
}

// Parse errors are errors, not an empty module.
func TestSyntaxErrorFails(t *testing.T) {
	dir := fixtureModule(t, map[string]string{"m.go": "package m\n\nfunc F( {\n"})
	prof := profile(t, dir, block("m.go", 3, 1, 3, 5, 1, 1))
	if _, err := crap.Score(dir, prof, crap.Options{Build: linux}); err == nil {
		t.Error("a module that does not parse was scored")
	}
}

func TestKeysDoNotDependOnTheDirectoryOfTheRun(t *testing.T) {
	dir := fixtureModule(t, map[string]string{"m.go": "package m\n\nfunc F() int {\n\treturn 1\n}\n"})
	prof := profile(t, dir, block("m.go", 3, 14, 5, 2, 1, 1))
	rel, err := filepath.Rel(".", dir)
	if err != nil {
		t.Skip("no relative path to the fixture")
	}
	a := keysOf(scoreOf(t, dir, prof, true))
	b := keysOf(scoreOf(t, rel, prof, true))
	if !slices.Equal(a, b) {
		t.Errorf("absolute dir %v, relative dir %v", a, b)
	}
}

// Composite-literal package literals get distinct keys: one variable, several
// literals, is a repeated key within one file, so each gains "#n" in source
// order (§6.7).
func TestCompositeLiteralsGetDistinctKeys(t *testing.T) {
	src := `package m

var table = map[string]func(int) int{
	"one": func(n int) int { return n },
	"two": func(n int) int { return n + 1 },
}

var single = func() int { return 1 }
`
	dir := fixtureModule(t, map[string]string{"m.go": src})
	prof := profile(t, dir, block("m.go", 4, 25, 4, 36, 1, 1))
	got := keysOf(scoreOf(t, dir, prof, true))
	want := []string{module + ".single", module + ".table@m.go#1", module + ".table@m.go#2"}
	if !slices.Equal(got, want) {
		t.Errorf("keys %v, want %v", got, want)
	}
}

// The existence set holds every identity in any .go file, whatever its tags:
// the functions the run compiles, the ones another platform compiles, and the
// ones no platform compiles.
func TestExistenceSetCoversEveryFile(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"main.go":      "package m\n\nfunc Run() { println() }\n",
		"w_windows.go": "package m\n\nfunc OnWindows() {}\n",
		"tagged.go":    "//go:build integration\n\npackage m\n\nfunc Tagged() {}\n",
		"ignored.go":   "//go:build ignore\n\npackage main\n\nfunc main() {}\n",
	})
	prof := profile(t, dir, block("main.go", 3, 14, 3, 25, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	want := []string{
		module + ".OnWindows", module + ".Run", module + ".Tagged", module + ".main",
	}
	if got := rep.Keys(); !slices.Equal(got, want) {
		t.Errorf("existence set %v, want %v", got, want)
	}
	if !rep.Exists(module+".Tagged") || rep.Exists(module+".Absent") {
		t.Error("Exists disagrees with the set")
	}
	if len(rep.Measured) != 1 || len(rep.NotMeasured) != 3 {
		t.Errorf("measured %d, not measured %d; want 1 and 3", len(rep.Measured), len(rep.NotMeasured))
	}
}

// Compiled answers, for a named build, which functions that build measures: a
// leg that is not the ledger leg asks it with the ledger's build (ruling C3).
func TestCompiledFollowsTheNamedBuild(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"main.go":      "package m\n\nfunc Run() {}\n",
		"x_linux.go":   "package m\n\nfunc Foo() {}\n",
		"x_windows.go": "package m\n\nfunc Foo() {}\n",
		"tagged.go":    "//go:build integration\n\npackage m\n\nfunc Tagged() {}\n",
	})
	linuxKeys, err := crap.Compiled(dir, linux)
	if err != nil {
		t.Fatal(err)
	}
	windows, err := crap.Compiled(dir, linux.Platform("windows", "amd64"))
	if err != nil {
		t.Fatal(err)
	}
	tagged, err := crap.Compiled(dir, gobuild.Build{GOOS: "linux", GOARCH: "amd64", Tags: []string{"integration"}})
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name string
		got  map[string]bool
		want []string
	}{
		{"linux", linuxKeys, []string{module + ".Foo@x_linux.go", module + ".Run"}},
		{"windows", windows, []string{module + ".Foo@x_windows.go", module + ".Run"}},
		{"linux with the integration tag", tagged, []string{module + ".Foo@x_linux.go", module + ".Run", module + ".Tagged"}},
	}
	for _, c := range cases {
		var got []string
		for k := range c.got {
			got = append(got, k)
		}
		slices.Sort(got)
		if !slices.Equal(got, c.want) {
			t.Errorf("%s: compiled %v, want %v", c.name, got, c.want)
		}
	}
}

// The build the profile came from decides which files are measured: the test
// run is `go test -race`, so a file behind !race is not compiled by it.
func TestRaceTagDecidesWhatIsMeasured(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"norace.go": "//go:build !race\n\npackage m\n\nfunc Plain() {}\n",
		"race.go":   "//go:build race\n\npackage m\n\nfunc Raced() { println() }\n",
	})
	prof := profile(t, dir, block("race.go", 5, 18, 5, 28, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	if len(rep.Measured) != 1 || rep.Measured[0].Name != "Raced" {
		t.Errorf("measured %+v, want the race file's function", rep.Measured)
	}
	if len(rep.NotMeasured) != 1 || rep.NotMeasured[0].Name != "Plain" {
		t.Errorf("not measured %+v, want the !race file's function", rep.NotMeasured)
	}
}

// A package whose only files need cgo vanishes from a load with cgo off. Its
// functions must still be listed, as not measured, never dropped.
func TestCgoOnlyPackageIsNotMeasuredNotDropped(t *testing.T) {
	cgoSrc := "package c\n\n/*\nstatic int one(void) { return 1; }\n*/\nimport \"C\"\n\nfunc One() int { return int(C.one()) }\n"
	dir := fixtureModule(t, map[string]string{
		"main.go": "package m\n\nfunc Run() { println() }\n",
		"c/c.go":  cgoSrc,
	})
	prof := profile(t, dir, block("main.go", 3, 14, 3, 25, 1, 1))
	rep := scoreOf(t, dir, prof, true) // cgo off
	if len(rep.NotMeasured) != 1 || rep.NotMeasured[0].Key != module+"/c.One" || !rep.Exists(module+"/c.One") {
		t.Errorf("not measured %+v, want %s/c.One", rep.NotMeasured, module)
	}
}

// Under ./... the go command drops a package whose files are all excluded by
// the build, with no error: here a package of _windows.go files on a linux run.
// The scan walks every file, so the package is neither lost from the existence
// set nor from the not-measured list.
func TestPackageOfOnlyOtherPlatformFilesIsNotLost(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"main.go":        "package m\n\nfunc Run() { println() }\n",
		"w/w_windows.go": "package w\n\nfunc Win() {}\n\nfunc Win2(a bool) {\n\tif a {\n\t\treturn\n\t}\n}\n",
		"d/d_darwin.go":  "package d\n\nfunc Darwin() {}\n",
	})
	prof := profile(t, dir, block("main.go", 3, 14, 3, 25, 1, 1))
	rep := scoreOf(t, dir, prof, true)
	for _, key := range []string{module + "/w.Win", module + "/w.Win2", module + "/d.Darwin"} {
		if !rep.Exists(key) {
			t.Errorf("%s is not in the existence set %v", key, rep.Keys())
		}
	}
	var nm []string
	for _, f := range rep.NotMeasured {
		nm = append(nm, f.Key)
	}
	slices.Sort(nm)
	want := []string{module + "/d.Darwin", module + "/w.Win", module + "/w.Win2"}
	if !slices.Equal(nm, want) {
		t.Errorf("not measured %v, want %v", nm, want)
	}
	for _, f := range rep.NotMeasured {
		if f.Key == module+"/w.Win2" && f.Comp != 2 {
			t.Errorf("Win2: comp %d, want 2", f.Comp)
		}
	}
}

// Exist reads every production file, whatever its tags, and runs no test and
// no build: `baseline --rename` calls it without a profile or a toolchain.
func TestExistNeedsNoProfileAndNoToolchain(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"main.go":        "package m\n\nfunc Run() {}\n",
		"types.go":       "package m\n\ntype T struct{}\n",
		"w/w_windows.go": "package w\n\nfunc Win() {}\n",
		"only/types.go":  "package only\n\ntype X int\n",
		"c/c.go":         "package c\n\nimport \"C\"\n\nfunc One() {}\n",
		"gen/g.go":       "// Code generated by a tool. DO NOT EDIT.\n\npackage gen\n\nfunc G() {}\n",
		"m_test.go":      "package m\n\nfunc helper() {}\n",
		"testdata/t.go":  "package td\n\nfunc T() {}\n",
		"sub/go.mod":     "module example.com/other\n\ngo 1.26\n",
		"sub/s.go":       "package sub\n\nfunc S() {}\n",
	})
	t.Setenv("PATH", t.TempDir())
	ex, err := crap.Exist(dir)
	if err != nil {
		t.Fatal(err)
	}
	wantKeys := []string{module + ".Run", module + "/c.One", module + "/w.Win"}
	if !slices.Equal(ex.Keys, wantKeys) {
		t.Errorf("keys %v, want %v", ex.Keys, wantKeys)
	}
	wantPkgs := []string{module, module + "/c", module + "/only", module + "/w"}
	if !slices.Equal(ex.Packages, wantPkgs) {
		t.Errorf("packages %v, want %v: a package with no function is still a package, a generated-only one is not", ex.Packages, wantPkgs)
	}
}

// What Exist reports is what Score reports as the existence set.
func TestExistAgreesWithScore(t *testing.T) {
	dir := fixtureModule(t, map[string]string{
		"main.go":      "package m\n\nfunc Run() { println() }\n\nfunc init() {}\n\nfunc init() {}\n",
		"x_windows.go": "package m\n\nfunc Win() {}\n",
		"tagged.go":    "//go:build integration\n\npackage m\n\nfunc Tagged() {}\n",
	})
	rep := scoreOf(t, dir, profile(t, dir, block("main.go", 3, 14, 3, 25, 1, 1)), true)
	ex, err := crap.Exist(dir)
	if err != nil {
		t.Fatal(err)
	}
	if got := rep.Keys(); !slices.Equal(got, ex.Keys) {
		t.Errorf("Score's existence set %v, Exist %v", got, ex.Keys)
	}
}

func TestExistFailsWithoutAModule(t *testing.T) {
	if _, err := crap.Exist(t.TempDir()); err == nil {
		t.Error("a directory with no go.mod was listed")
	}
}

// The count of platform loads is the cost of typing the not-measured functions:
// one load for each platform that compiles at least one of their files, and
// none for a file no platform compiles or when the discount is off.
func TestPlatformLoadsAreCountedPerPlatformThatCompilesAFile(t *testing.T) {
	one := fixtureModule(t, map[string]string{
		"main.go":      "package m\n\nfunc Run() { println() }\n",
		"a_windows.go": "package m\n\nfunc A() {}\n",
		"b_windows.go": "package m\n\nfunc B() {}\n",
	})
	prof := profile(t, one, block("main.go", 3, 14, 3, 25, 1, 1))
	if n := scoreOf(t, one, prof, true).PlatformLoads; n != 1 {
		t.Errorf("two windows files: %d loads, want 1", n)
	}
	two := fixtureModule(t, map[string]string{
		"main.go":      "package m\n\nfunc Run() { println() }\n",
		"a_windows.go": "package m\n\nfunc A() {}\n",
		"b_darwin.go":  "package m\n\nfunc B() {}\n",
	})
	prof = profile(t, two, block("main.go", 3, 14, 3, 25, 1, 1))
	if n := scoreOf(t, two, prof, true).PlatformLoads; n != 2 {
		t.Errorf("a windows and a darwin file: %d loads, want 2", n)
	}
	if n := scoreOf(t, two, prof, false).PlatformLoads; n != 0 {
		t.Errorf("discount off: %d loads, want 0: nothing to type", n)
	}
	none := fixtureModule(t, map[string]string{
		"main.go":   "package m\n\nfunc Run() { println() }\n",
		"tagged.go": "//go:build integration\n\npackage m\n\nfunc T() {}\n",
	})
	prof = profile(t, none, block("main.go", 3, 14, 3, 25, 1, 1))
	if n := scoreOf(t, none, prof, true).PlatformLoads; n != 0 {
		t.Errorf("a file no platform compiles: %d loads, want 0", n)
	}
}
